// Tiny deterministic media for isolated browser fixtures; no external or user files.
export const syntheticMp4 = Buffer.from('', 'base64')
export const syntheticPng = Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+aDKsAAAAASUVORK5CYII=', 'base64')

// Native media seeking requires byte-range responses, even for tiny fixtures.
export function syntheticMp4Response(range) {
  const match = range?.match(/^bytes=(\d+)-(\d*)$/)
  if (!match) return { contentType: 'video/mp4', headers: { 'accept-ranges': 'bytes' }, body: syntheticMp4 }
  const start = Number(match[1])
  const end = match[2] ? Math.min(Number(match[2]), syntheticMp4.length - 1) : syntheticMp4.length - 1
  return {
    status: 206, contentType: 'video/mp4',
    headers: { 'accept-ranges': 'bytes', 'content-range': `bytes ${start}-${end}/${syntheticMp4.length}` },
    body: syntheticMp4.subarray(start, end + 1)
  }
}
